-- State transitions declared for ProcessingJob: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.processing_jobs_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('completed', 'pending'), ('failed', 'pending'), ('pending', 'cancelled'), ('pending', 'completed'), ('pending', 'failed'), ('pending', 'running'), ('running', 'cancelled'), ('running', 'completed'), ('running', 'failed'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: processing_jobs.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_processing_jobs__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS processing_jobs_status_transition_check ON bucket.processing_jobs;
CREATE TRIGGER processing_jobs_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.processing_jobs
    FOR EACH ROW EXECUTE FUNCTION bucket.processing_jobs_status_transition_check();
